        'Create',
        LEFT(USER(), 80),
        CONCAT('Persona creada. ', 'ID: ', NEW.person_ID, '. Datos: ', JSON_OBJECT(
            'person_ID', NEW.person_ID,
            'user_ID', NEW.user_ID,
            'courtesy_title', NEW.courtesy_title,
            'given_names', NEW.given_names,
            'family_names', NEW.family_names,
