CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_pick_gender`(p_pct_female DECIMAL(5,2), p_pct_undisclosed DECIMAL(5,2)) RETURNS varchar(30) CHARSET utf8mb4
    NO SQL
    COMMENT 'Hombre / Mujer / Prefiero no decirlo según los porcentajes indicados'
BEGIN
    IF fn_gen_chance(p_pct_undisclosed) = 1 THEN
        RETURN 'Prefiero no decirlo';
    END IF;
    IF fn_gen_chance(p_pct_female) = 1 THEN
        RETURN 'Mujer';
    END IF;
    RETURN 'Hombre';
END ;;
