CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_random_datetime`(p_from DATETIME, p_to DATETIME) RETURNS datetime
    NO SQL
    COMMENT 'Fecha-hora aleatoria uniforme entre p_from y p_to'
BEGIN
    IF p_to <= p_from THEN
        RETURN p_from;
    END IF;
    RETURN DATE_ADD(
        p_from,
        INTERVAL FLOOR(RAND() * (TIMESTAMPDIFF(SECOND, p_from, p_to) + 1)) SECOND
    );
END ;;
DELIMITER ;
